components.css:
.ds-header { color:#e1e8ee; background:#20252b; font:400 14px/1.45 Roboto,sans-serif; }
.ds-header button { display:inline-flex; align-items:center; justify-content:center; gap:.5rem; min-height:36px; padding:.5rem 1rem; font:inherit; color:inherit; background:#282f37; border:1px solid #424d59; border-radius:5px; cursor:pointer; transition:background-color 120ms ease-out,border-color 120ms ease-out; }
.ds-header button:hover:not(:disabled) { background:#35414d; border-color:#667788; }
.ds-header button:focus-visible,.ds-header summary:focus-visible { outline:2px solid #79b7d4; outline-offset:2px; }
.ds-header button:disabled { opacity:.45; cursor:default; }
@media(max-width:1050px) { .ds-header button { min-height:44px; } }
@media(prefers-reduced-motion:reduce) { .ds-header button { transition:none; } }
.ds-header { display:flex; align-items:center; gap:.5rem; padding:.5rem 1rem; border-bottom:1px solid #424d59; }
.ds-header h1 { flex:1; min-width:0; margin:0; font-size:18px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.ds-header small { color:#a5b3c0; }
.ds-header button[data-primary] { background:#326b85; border-color:#326b85; color:#fff; }
.ds-header button[data-primary]:hover { background:#3b7c99; border-color:#3b7c99; }
.ds-project-actions { display:contents; }
.ds-project-actions > button { display:none; }
.ds-project-actions > div { display:flex; align-items:center; gap:.5rem; }
@media(max-width:1050px) { .ds-header { padding:.5rem; } .ds-header h1 { font-size:1.2rem; } .ds-header .ds-desktop { display:none; } .ds-header > button { padding:.5rem; } .ds-header button[data-primary] span { font-size:13px; } .ds-project-actions { display:block; } .ds-project-actions > button { display:inline-flex; } .ds-project-actions > div { display:none; } }

.ds-stage { color:#e1e8ee; background:#20252b; font:400 14px/1.45 Roboto,sans-serif; }
.ds-stage button { display:inline-flex; align-items:center; justify-content:center; gap:.5rem; min-height:36px; padding:.5rem 1rem; font:inherit; color:inherit; background:#282f37; border:1px solid #424d59; border-radius:5px; cursor:pointer; transition:background-color 120ms ease-out,border-color 120ms ease-out; }
.ds-stage button:hover:not(:disabled) { background:#35414d; border-color:#667788; }
.ds-stage button:focus-visible,.ds-stage summary:focus-visible { outline:2px solid #79b7d4; outline-offset:2px; }
.ds-stage button:disabled { opacity:.45; cursor:default; }
@media(max-width:1050px) { .ds-stage button { min-height:44px; } }
@media(prefers-reduced-motion:reduce) { .ds-stage button { transition:none; } }
.ds-stage { display:flex; overflow-x:auto; border-bottom:1px solid #424d59; }
.ds-stage button { border:0; border-bottom:2px solid transparent; border-radius:0; background:transparent; padding:.5rem 1.5rem; }
.ds-stage button[aria-current="step"] { color:#79b7d4; border-bottom-color:#79b7d4; }
.ds-workspace-actions { margin-left:auto; display:flex; align-items:center; gap:.25rem; padding:.25rem .5rem; }
.ds-workspace-actions button { border-radius:5px; padding:.5rem; }
@media(max-width:1050px) { .ds-stage { flex-wrap:wrap; } .ds-stage button { flex:1; flex-direction:column; font-size:.8rem; padding:.5rem; gap:.25rem; } .ds-workspace-actions { width:100%; border-top:1px solid #424d59; justify-content:flex-end; flex-wrap:wrap; } .ds-workspace-actions button { flex:initial; flex-direction:row; font-size:13px; } }
@media(max-width:600px) { .ds-stage > button { flex-direction:row; } .ds-stage > button > svg { display:none; } }

.ds-inspector { width:320px; max-width:100%; color:#e1e8ee; background:#282f37; font:400 14px/1.45 Roboto,sans-serif; padding:1rem; border-left:1px solid #424d59; }
.ds-inspector h2 { font-size:18px; margin:0 0 1rem; }
.ds-inspector h3 { font-size:1rem; margin:1.5rem 0 1rem; }
.ds-inspector button,.ds-inspector input,.ds-inspector select { font:inherit; color:inherit; background:#282f37; border:1px solid #424d59; border-radius:5px; min-height:36px; padding:.5rem; }
.ds-inspector button { cursor:pointer; transition:background-color 120ms ease-out,border-color 120ms ease-out; }
.ds-inspector button:hover:not(:disabled) { background:#35414d; border-color:#667788; }
.ds-inspector button:focus-visible,.ds-inspector input:focus-visible,.ds-inspector select:focus-visible,.ds-inspector summary:focus-visible { outline:2px solid #79b7d4; outline-offset:2px; }
.ds-inspector button:disabled { opacity:.45; cursor:default; }
.ds-inspector ul { list-style:none; padding:0; margin:0; }
.ds-inspector li { display:grid; grid-template-columns:minmax(0,1fr) auto; align-items:center; border-bottom:1px solid #424d59; gap:.25rem; padding:.25rem 0; }
.ds-inspector li button { border-color:transparent; background:transparent; }
.ds-inspector .ds-key-select { min-width:0; display:grid; grid-template-columns:auto minmax(0,1fr); align-items:center; gap:.5rem; text-align:left; overflow-wrap:anywhere; }
.ds-key-select span { white-space:nowrap; }
.ds-key-select small { font-size:13px; color:#a5b3c0; }
.ds-inspector .ds-key-remove { width:36px; color:#a5b3c0; display:inline-flex; align-items:center; justify-content:center; }
.ds-inspector .ds-key-remove:hover:not(:disabled) { color:#ff6d6d; }
.ds-matrix { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:.5rem; margin-bottom:1.5rem; }
.ds-inspector .ds-matrix-settings,.ds-inspector .ds-matrix-delete { grid-column:1/-1; text-align:left; }
.ds-inspector .ds-matrix-settings { color:#79b7d4; }
.ds-inspector .ds-matrix-delete { color:#ff6d6d; border-color:transparent; background:transparent; }
.ds-inspector fieldset { min-width:0; border:0; border-top:1px solid #424d59; margin:1.5rem 0 0; padding:1rem 0 0; }
.ds-inspector legend { font-weight:600; padding:0 .5rem 0 0; }
.ds-relative { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:.5rem; margin:.5rem 0; }
.ds-relative label { display:grid; gap:.5rem; min-width:0; }
.ds-relative input { min-width:0; background:#20262d; caret-color:#79b7d4; font-variant-numeric:tabular-nums; }
@media(max-width:1050px) { .ds-inspector button,.ds-inspector input { min-height:44px; } .ds-inspector .ds-key-remove { width:44px; } }
@media(prefers-reduced-motion:reduce) { .ds-inspector button { transition:none; } }
.ds-inspector p { color:#c0ccd6; overflow-wrap:anywhere; }
.ds-inspector summary { cursor:pointer; padding:.5rem 0; font-weight:500; }
.ds-inspector-field { display:grid; grid-template-columns:minmax(70px,.85fr) minmax(0,1fr); align-items:center; gap:.5rem; margin:.5rem 0; }
.ds-inspector-field input,.ds-inspector-field select { width:100%; min-width:0; background:#20262d; caret-color:#79b7d4; font-variant-numeric:tabular-nums; }
.ds-stagger-presets { display:flex; flex-wrap:wrap; gap:.5rem; margin:.5rem 0; }
@media(max-width:1050px) { .ds-inspector { border-left:0; border-top:1px solid #424d59; } .ds-inspector input,.ds-inspector select { min-height:44px; } }

.ds-status { color:#e1e8ee; background:#20252b; font:400 14px/1.45 Roboto,sans-serif; }
.ds-status button { display:inline-flex; align-items:center; justify-content:center; gap:.5rem; min-height:36px; padding:.5rem 1rem; font:inherit; color:inherit; background:#282f37; border:1px solid #424d59; border-radius:5px; cursor:pointer; transition:background-color 120ms ease-out,border-color 120ms ease-out; }
.ds-status button:hover:not(:disabled) { background:#35414d; border-color:#667788; }
.ds-status button:focus-visible,.ds-status summary:focus-visible { outline:2px solid #79b7d4; outline-offset:2px; }
.ds-status button:disabled { opacity:.45; cursor:default; }
@media(max-width:1050px) { .ds-status button { min-height:44px; } }
@media(prefers-reduced-motion:reduce) { .ds-status button { transition:none; } }
.ds-status { display:flex; align-items:center; flex-wrap:wrap; gap:.5rem; padding:.5rem 1rem; border-top:1px solid #424d59; font-size:13px; } .ds-status small { color:#a5b3c0; line-height:1.4; } .ds-status button { margin-left:auto; }
